<?php
if(!defined('ABSPATH')){exit(1);}global$wpdb;$f=get_option('cvt_logistics_fixture');$id=absint($f['order_id']);$order=wc_get_order($id);$assert=static function($ok,$message){if(!$ok){throw new RuntimeException($message);}};
$assert('ready'===$order->get_meta('_cvd_operation_status',true),'operation no quedó ready');$assert('to_store'===$order->get_meta('_cvd_delivery_status',true),'delivery no quedó to_store');$winner=absint($order->get_meta('_cvd_messenger_user_id',true));$assert(in_array($winner,array(absint($f['messenger_one']),absint($f['messenger_two'])),true),'ganador inválido');$assert((bool)$order->get_meta('_cvd_to_store_at',true),'falta timestamp to_store');$invited=array_map('absint',(array)$order->get_meta('_cvd_delivery_invited_messengers',true));$assert(in_array(absint($f['messenger_one']),$invited,true)&&in_array(absint($f['messenger_two']),$invited,true),'invitados no conservados');
$table=$wpdb->prefix.'cvd_order_events';foreach(array('operation:ready','delivery:offered','delivery:accepted','delivery:to_store')as$pair){list($domain,$to)=explode(':',$pair);$count=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$table} WHERE order_id=%d AND domain=%s AND to_state=%s",$id,$domain,$to));$assert(1===$count,'evento duplicado/ausente: '.$pair);}
$receipts=$order->get_meta('_cvd_transition_receipts',true);$assert(is_array($receipts)&&count($receipts)>=3,'faltan receipts idempotentes');$history=(array)$order->get_meta('_cvd_delivery_history',true);$assert(3===count(array_filter($history,static fn($e)=>in_array($e['to'],array('offered','accepted','to_store'),true))),'historial legacy duplicado');
$direct=wc_get_order(absint($f['direct_order_id']));$assert('assigned'===$direct->get_meta('_cvd_delivery_status',true)&&absint($f['messenger_one'])===absint($direct->get_meta('_cvd_messenger_user_id',true)),'asignación directa inconsistente');echo "OK: logística 1C.1 verificada directamente en MariaDB.\n";
